import { getGraphToken } from "./auth";

Office.onReady((info) => {
  const statusBox = document.getElementById("status-text");

  if (statusBox) {
    statusBox.innerHTML =
      `Handshake complete! Connected to ${info.host}.`;
  }

  const runButton = document.getElementById("run");

  if (runButton) {
    runButton.onclick = run;
  }

  const graphButton = document.getElementById("graph-test");

  if (graphButton) {
    graphButton.onclick = async () => {
      try {
        if (statusBox) {
          statusBox.innerHTML = "Logging in...";
        }

        const token = await getGraphToken();

        console.log("Graph Token:", token);

        if (statusBox) {
          statusBox.innerHTML =
            `SUCCESS: Token received (${token.substring(0, 20)}...)`;
        }

      } catch (error: any) {
        console.error("Graph Error:", error);

        if (statusBox) {
          statusBox.innerHTML =
            `Graph Error: ${error.message || JSON.stringify(error)}`;
        }
      }
    };
  }
});

export async function run(): Promise<void> {
  const statusBox = document.getElementById("status-text");

  try {
    await Excel.run(async (context) => {
      const workbook = context.workbook;

      const existingSheet =
        workbook.worksheets.getItemOrNullObject("Control_Panel");

      await context.sync();

      let targetSheet: Excel.Worksheet;

      if (existingSheet.isNullObject) {
        targetSheet = workbook.worksheets.add("Control_Panel");

        if (statusBox) {
          statusBox.innerHTML =
            "SUCCESS: Created a new 'Control_Panel' worksheet.";
        }
      } else {
        targetSheet = existingSheet;

        if (statusBox) {
          statusBox.innerHTML =
            "'Control_Panel' worksheet already exists.";
        }
      }

      targetSheet.activate();

      await context.sync();
    });
  } catch (error: any) {
    console.error("Excel Error:", error);

    if (statusBox) {
      statusBox.innerHTML =
        `ERROR: ${error.message || JSON.stringify(error)}`;
    }
  }
}