import {
  PublicClientApplication,
  AuthenticationResult
} from "@azure/msal-browser";

const msalConfig = {
  auth: {
    clientId: "47cf08d5-389b-40bf-884e-193b6d9ee995",
    authority: "https://login.microsoftonline.com/f285c292-6d27-443d-a1f0-dd70bcc4de16",
    redirectUri: "https://cordusbailey02.github.io/PayrollAddin/taskpane.html"
  }
};

const loginRequest = {
  scopes: [
    "User.Read",
    "Files.Read.All",
    "Sites.Read.All"
  ]
};

const msalInstance =
  new PublicClientApplication(msalConfig);

let initialized = false;

async function ensureInitialized() {
  if (!initialized) {
    console.log("MSAL initializing...");
    await msalInstance.initialize();

    await msalInstance.handleRedirectPromise();

    console.log("MSAL redirect processed");
    initialized = true;
  }
}

export async function getGraphToken(): Promise<string> {

  await ensureInitialized();

  const accounts = msalInstance.getAllAccounts();

  if (accounts.length > 0) {
    try {
      const response: AuthenticationResult =
        await msalInstance.acquireTokenSilent({
          ...loginRequest,
          account: accounts[0]
        });

      return response.accessToken;

    } catch {
      // silent failed
    }
  }

  const loginResponse =
    await msalInstance.loginPopup(loginRequest);

  return loginResponse.accessToken;
}